'use strict';

const { runPy } = require('../helper');

/**
 * combine all the data (one day) into 1 npz
 *  + `summarizeOnly`:
 *    - if true, will only store the summarized data (per day) into 1 npz
 *    - if false or not specified, the original npzs will be deleted after the process is done.
 */
function combine(
  cameraId,
  {
    start = Date.now() - 86400000,
    end = Date.now(),
    summarizeOnly = false,
    motion = false,
    step = 15, // in minute
    ...rest
  } = {},
  srcDir = './data',
) {
  const id = cameraId

  const args = [
    '-id', id,
    '-npz_dir', srcDir,
    '-s', start,
    '-e', end,
  ]

  if (summarizeOnly) {
    args.push('-last')
  }

  if (motion) {
    args.push('-motion')

    args.push('-step')
    args.push(parseInt(step))
  }

  return runPy('combine_npz.py', {
    args,
    ...rest,
  })
}

module.exports = combine;
